/* PickPack 1291 — prototype only. Independent implementation inspired by Horilla's published UI patterns. No API, auth, storage, or provider calls. */
(()=>{
'use strict';
const root=document.getElementById('root');
const PAGES={dashboard:{title:'Tổng quan',desc:'Tình hình vận hành Pick Pack 1291'},people:{title:'Nhân sự',desc:'Danh sách và hồ sơ nhân sự'},shifts:{title:'Ra / vào ca',desc:'Theo dõi quét ca và user làm việc'},labor:{title:'Công nhật',desc:'Tổng hợp công theo ngày và ca'},minutes:{title:'Biên bản',desc:'Quản lý và lưu trữ biên bản'},assets:{title:'Công cụ dụng cụ',desc:'Danh mục, tình trạng và cấp phát'},pda:{title:'Mượn / trả PDA',desc:'Theo dõi thiết bị và người đang sử dụng'}};
const SIDEBAR=[{name:'BẢNG ĐIỀU KHIỂN',items:[['dashboard','grid']]},{name:'QUẢN LÝ NHÂN SỰ',items:[['people','users'],['shifts','clock'],['labor','calendar']]},{name:'HỒ SƠ & THIẾT BỊ',items:[['minutes','file'],['assets','boxes'],['pda','device']]}];
const PATHS={
grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a6 6 0 0 1 12 0v2M17 3a4 4 0 0 1 0 8M17 15a6 6 0 0 1 5 6"/>',
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 2v6M16 2v6M3 10h18M8 14h3M8 18h3"/>',
file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6"/>',
boxes:'<path d="m12 2 9 5-9 5-9-5-9-5zM3 7v10l9 5 9-5V7M12 12v10"/>'.replace('l9-5-9-5-9-5','l-9 5-9-5'),
device:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 5h4M11 18h2"/>',
search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
moon:'<path d="M20 14A9 9 0 0 1 10 4a9 9 0 1 0 10 10z"/>',
list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
edit:'<path d="M4 20l5-1 10-10-4-4L5 15zM13 7l4 4"/>',
trash:'<path d="M4 7h16M10 3h4M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',
eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7z"/><circle cx="12" cy="12" r="3"/>',
download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
plus:'<path d="M12 5v14M5 12h14"/>',
logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>'
};
function icon(name,size=18){return `<svg class="ui-svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PATHS[name]||PATHS.grid}</svg>`}
const ICONS=Object.fromEntries(['grid','users','clock','calendar','file','boxes','device'].map(k=>[k,icon(k)]));
// Completely synthetic, reproducible operational examples. No real employee or device records.
const STORAGE_KEY='pickpack1291_office_records_v06';
const FONT_KEY='pickpack1291_office_font_v06';
const THEME_KEY='pickpack1291_office_theme_v06';
const SESSION_KEY='pickpack1291_office_session_v06';
function storageGet(key){try{return localStorage.getItem(key)}catch{return null}}
function storageSet(key,val){try{localStorage.setItem(key,val);return true}catch{return false}}
function storageRemove(key){try{localStorage.removeItem(key)}catch{}}
function demoSession(){return storageGet(SESSION_KEY)==='demo-admin-only'||(location.protocol==='file:'&&new URLSearchParams(location.search).get('demo')==='1')}
function seedRecords(){
 const family=['Nguyễn','Trần','Lê','Phạm','Hoàng','Vũ','Đặng','Bùi','Đỗ','Phan','Ngô','Hồ'];
 const middle=['Minh','Thị','Văn','Hồng','Quang','Thanh','Đức','Ngọc','Gia','Tuấn'];
 const given=['An','Bình','Châu','Dũng','Giang','Hà','Hải','Hạnh','Huy','Khánh','Lan','Linh','Long','Mai','Nam','Nhi','Phúc','Quân','Sơn','Trang','Vy','Yến'];
 const states=['Đang làm việc','Chờ vào ca','Nghỉ ca'];
 const people=Array.from({length:36},(_,i)=>({id:`NV-${String(i+1).padStart(3,'0')}`,name:`${family[i%family.length]} ${middle[(i*3+2)%middle.length]} ${given[(i*5+3)%given.length]}`,team:['Pick','Pack','Auto Pack','Điều phối'][i%4],shift:i%3===0?'Ca 2':'Ca 1',user:`hy1291.user${String(i+1).padStart(3,'0')}`,state:states[i%3],email:`office-nv${String(i+1).padStart(3,'0')}@example.invalid`,initial:`M${(i%9)+1}`}));
 const shifts=Array.from({length:42},(_,i)=>{const person=people[i%people.length],end=i%4===0;return {id:`CA-${String(i+1).padStart(3,'0')}`,name:person.name,staff:person.id,date:`${String(14-Math.floor(i/8)).padStart(2,'0')}/11/2026`,shift:person.shift,checkin:i%5===0?'—':`0${5+(i%3)}:${String(28+i%31).padStart(2,'0')}`,checkout:end?'14:0'+(i%9):'—',user:person.user,state:end?'Đã ra ca':i%5===0?'Chờ vào ca':'Trong ca'};});
 const labor=Array.from({length:42},(_,i)=>{const person=people[(i*7)%people.length];return {id:`CN-${String(i+1).padStart(3,'0')}`,name:person.name,date:`${String(14-Math.floor(i/9)).padStart(2,'0')}/11/2026`,shift:person.shift,work:person.team,hours:['8,0','8,5','9,0','0,0'][i%4],state:['Đã xác nhận','Tạm tính','Chưa chấm'][i%3]};});
 const issueTypes=['Bàn giao ca','Thiết bị','Tác nghiệp','An toàn','Kỷ luật'];
 const minutes=Array.from({length:30},(_,i)=>({id:`BB-${String(i+1).padStart(3,'0')}`,name:`Biên bản ${issueTypes[i%issueTypes.length].toLowerCase()} — ${String(i+1).padStart(2,'0')}`,type:issueTypes[i%issueTypes.length],date:`${String(14-Math.floor(i/6)).padStart(2,'0')}/11/2026`,owner:people[(i*3)%people.length].name,state:['Chờ xác nhận','Đã lưu','Đã xác nhận'][i%3]}));
 const goods=['Máy quét mã vạch','Khay phân loại','Bộ sạc thiết bị','Xe đẩy hàng','Bút kiểm kho','Băng dính','Giỏ nhựa','Tem nhãn','Bộ đàm','Kéo an toàn','Găng tay','Bảng kê'];
 const assets=Array.from({length:30},(_,i)=>({id:`CCDC-${String(i+1).padStart(3,'0')}`,name:`${goods[i%goods.length]} — lô ${Math.floor(i/goods.length)+1}`,type:i%3===0?'Thiết bị':'Dụng cụ',qty:2+(i*7%19),unit:['chiếc','cái','bộ'][i%3],holder:['Kho CCDC','Khu Pick','Khu Pack','Khu Auto'][i%4],state:['Sẵn sàng','Đang sử dụng','Cần kiểm tra'][i%3]}));
 // 30 borrowing/return history entries across exactly three distinct demo PDA devices.
 const pda=Array.from({length:30},(_,i)=>({id:`MT-${String(i+1).padStart(3,'0')}`,name:`PDA-${String(i%3+1).padStart(2,'0')}`,holder:people[(i*2)%people.length].name,user:people[(i*2)%people.length].user,borrow:`0${5+(i%4)}:${String(20+i%37).padStart(2,'0')}`,return:i<2?'—':`1${4+i%3}:${String(10+i%39).padStart(2,'0')}`,state:i<2?'Đang mượn':'Đã trả'}));
 return {people,shifts,labor,minutes,assets,pda};
}
function readRecords(){try{const data=JSON.parse(storageGet(STORAGE_KEY)||'null');if(data&&Object.keys(seedRecords()).every(k=>Array.isArray(data[k])&&data[k].length<500))return data}catch{}return seedRecords()}
const store=readRecords();
function persist(){storageSet(STORAGE_KEY,JSON.stringify(store))}
function updateRecord(key,id,changes){const row=store[key]?.find(r=>r.id===id);if(!row)return false;Object.assign(row,changes);persist();return true}
const columns={
 people:[['name','Nhân sự'],['id','Mã NV'],['team','Bộ phận'],['shift','Ca'],['user','User làm việc'],['state','Trạng thái']],
 shifts:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['checkin','Vào ca'],['checkout','Ra ca'],['user','User làm việc'],['state','Trạng thái']],
 labor:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['work','Công việc'],['hours','Giờ công'],['state','Trạng thái']],
 minutes:[['name','Tên biên bản'],['id','Mã'],['type','Loại'],['date','Ngày'],['owner','Người lập'],['state','Trạng thái']],
 assets:[['name','Tên CCDC'],['id','Mã'],['type','Loại'],['qty','Số lượng'],['holder','Vị trí'],['state','Trạng thái']],
 pda:[['name','Thiết bị'],['holder','Người mượn'],['user','User làm việc'],['borrow','Giờ mượn'],['return','Giờ trả'],['state','Trạng thái']]
};
const state={view:'dashboard',theme:'light',fontPct:100,search:'',filter:'all',layout:'table',drawer:'',modal:'',sidebar:false,notice:'',editId:'',selected:new Set(),loginError:'',loginVisible:false};
const escape=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const qs=new URLSearchParams(location.search);state.view=PAGES[qs.get('view')]?qs.get('view'):'dashboard';state.theme=qs.has('theme')?(qs.get('theme')==='dark'?'dark':'light'):(storageGet(THEME_KEY)==='dark'?'dark':'light');state.fontPct=Math.max(90,Math.min(120,Number(storageGet(FONT_KEY))||100));state.drawer=qs.get('record')||'';
const href=(view=state.view,record='',theme=state.theme)=>`app.html?view=${encodeURIComponent(view)}&theme=${theme}`+(record?`&record=${encodeURIComponent(record)}`:'')+(location.protocol==='file:'?'&demo=1':'');
const badge=(v)=>{const s=String(v);const type=/Chờ|Cần kiểm tra|Chưa/.test(s)?'warn':/Đã lưu|Đã xác nhận|Sẵn sàng|Đã ra/.test(s)?'neutral':/Trong ca|Đang|Tạm tính/.test(s)?'good':'neutral';return `<span class="status ${type}"><span class="status-dot"></span>${escape(s)}</span>`};
const avatar=(x,big=false)=>`<span class="person-avatar ${big?'big':''}" aria-hidden="true">${escape(x.initial || String(x.name||'A').slice(-2).toUpperCase())}</span>`;
function side(){return `<aside class="sidebar ${state.sidebar?'is-open':''}" aria-label="Điều hướng PickPack"><div class="side-top"><img class="brand-logo" src="assets/supra-mark.png" alt="The Supra"><div><strong>PickPack 1291</strong><small>QUẢN LÝ VẬN HÀNH</small></div><button class="mobile-hide" data-action="close-nav" aria-label="Đóng menu">×</button></div><div class="sidebar-scroll"><div class="location-chip"><span class="location-icon">⌂</span><div><strong>Kho 1291</strong><small>Trung tâm vận hành</small></div><span class="caret">⌄</span></div>${SIDEBAR.map(group=>`<div class="side-group"><span class="group-title">${group.name}</span>${group.items.map(([view,icon])=>`<div class="side-link ${state.view===view?'selected':''}"><a class="nav-main" href="${href(view)}" data-nav="${view}" aria-current="${state.view===view?'page':'false'}" ><span class="nav-icon">${ICONS[icon]}</span><span>${PAGES[view].title}</span></a></div>`).join('')}</div>`).join('')}</div><div class="side-bottom"><span class="online-dot"></span><div><strong>Quản trị viên</strong><small>Quản trị hệ thống</small></div><button class="side-logout" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">${icon("logout",18)}</button></div></aside>`}
function top(){return `<header class="topbar"><div class="top-left"><button class="icon-button menu-button" data-action="toggle-nav" aria-label="Mở menu">☰</button><div class="breadcrumb">Hệ thống <span>›</span><strong>${PAGES[state.view].title}</strong></div></div><div class="top-right"><div class="top-search">${icon("search",17)}<input id="global-search" type="search" placeholder="Tìm nhanh trong ${PAGES[state.view].title.toLowerCase()}..." value="${escape(state.search)}" aria-label="Tìm nhanh"></div><span class="top-divider"></span><button class="icon-button" data-action="theme" title="Chuyển sáng/tối" aria-label="Chuyển chế độ màu">${icon(state.theme==="light"?"moon":"sun",19)}</button><button class="icon-button" data-action="settings" title="Cài đặt" aria-label="Cài đặt">${icon("settings",19)}</button><button class="icon-button notif" data-action="notifications" title="Thông báo mẫu" aria-label="Thông báo mẫu">${icon("bell",19)}<i></i></button><div class="top-profile">${avatar({initial:'AD'})}<div><strong>Quản trị viên</strong><small>Office Admin</small></div><span class="caret">⌄</span></div></div></header>`}
function pageHead(action='',other=''){return `<div class="page-header"><div><div class="eyebrow">PICK PACK 1291 / <span>${PAGES[state.view].title.toUpperCase()}</span></div><h1>${PAGES[state.view].title}</h1><p>${PAGES[state.view].desc}. </p></div><div class="header-actions">${other}${action}</div></div>`}
function stat(label,value,small,accent='blue',icon='▦'){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${accent}">${icon}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${small}</div></div>`}
function activity(){return `<section class="panel activity-panel"><div class="panel-title"><div><h2>Hoạt động gần đây</h2><p>Cập nhật nghiệp vụ gần đây</p></div><span class="muted">Hôm nay</span></div><div class="timeline">${[['09:12','Cấp phát PDA-02','Thiết bị · Khu Pick'],['08:36','Tạo biên bản bàn giao ca','Hồ sơ · Đang chờ xác nhận'],['06:12','Cập nhật user làm việc','Nhân sự · User làm việc'],['05:31','Ghi nhận nhân sự vào ca','Ra / vào ca · Ca 1']].map(([time,name,sub],i)=>`<div class="timeline-row"><span class="timeline-indicator ${i===0?'current':''}"></span><div><strong>${name}</strong><small>${sub}</small></div><time>${time}</time></div>`).join('')}</div></section>`}
function workload(){const points=[38,55,43,73,62,86,68],labs=['05h','07h','09h','11h','13h','15h','17h'];return `<section class="panel chart-panel"><div class="panel-title"><div><h2>Phân bổ nhân sự theo giờ</h2><p>Lưu lượng theo khung giờ</p></div><span class="legend"><i></i>Đang làm việc</span></div><div class="chart-area"><div class="chart-lines"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div class="chart-bars">${points.map((x,i)=>`<div class="chart-col"><div class="bar-wrap"><div class="bar" style="height:${x}%"><span>${x}%</span></div></div><small>${labs[i]}</small></div>`).join('')}</div></div></section>`}
function attention(){return `<section class="panel alert-panel"><div class="panel-title"><div><h2>Cần kiểm tra</h2><p>Các mục cần xử lý</p></div><span class="bubble">03</span></div><div class="alert-list"><a href="${href('minutes')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>Biên bản chờ xác nhận</strong><small>Hồ sơ cần xác nhận</small></span><span>›</span></a><a href="${href('assets')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>CCDC cần kiểm tra</strong><small>Thiết bị chờ kiểm tra</small></span><span>›</span></a><a href="${href('shifts')}" class="alert-row"><span class="alert-icon blue">◷</span><span><strong>Nhân sự chờ vào ca</strong><small>Hồ sơ cần xác nhận</small></span><span>›</span></a></div></section>`}
function dashboard(){return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">${icon("plus",16)} Tạo biên bản</button>`)}<div class="metrics">${stat('Tổng nhân sự',String(store.people.length).padStart(2,'0'),'Danh sách hồ sơ','blue','♙')}${stat('Đang trong ca',String(store.shifts.filter(r=>r.state==='Trong ca').length).padStart(2,'0'),'Theo dõi ra / vào ca','green','◷')}${stat('PDA đang mượn',String(new Set(store.pda.filter(r=>r.state==='Đang mượn').map(r=>r.name)).size).padStart(2,'0')+' / 03','Thiết bị đang quản lý','purple','▯')}${stat('Biên bản chờ duyệt',String(store.minutes.filter(r=>r.state==='Chờ xác nhận').length).padStart(2,'0'),'Hồ sơ cần xử lý','orange','▤')}</div><div class="two-col">${workload()}${attention()}</div><div class="two-col lower">${activity()}<section class="panel shortcut-panel"><div class="panel-title"><div><h2>Truy cập nhanh</h2><p>Những chức năng dùng thường xuyên</p></div></div><div class="shortcut-grid">${[['people','♙','Tra cứu nhân sự'],['shifts','◷','Ghi nhận ra/vào'],['labor','▦','Bảng công nhật'],['minutes','▤','Biên bản'],['assets','▣','Kho CCDC'],['pda','▯','Mượn / trả PDA']].map(([view,ic,title])=>`<a href="${href(view)}" class="shortcut"><span>${ic}</span><strong>${title}</strong><small>→</small></a>`).join('')}</div></section></div></div>`}
function tableCell(row,key,view){if(key==='name')return `<div class="cell-name">${view==='people'?avatar(row):''}<div><strong>${escape(row.name)}</strong>${view==='people'?`<small>${escape(row.email)}</small>`:''}</div></div>`;if(key==='state')return badge(row[key]);if(key==='id')return `<span class="mono">${escape(row[key])}</span>`;return escape(row[key])}
function filtered(){const set=store[state.view]||[];let rows=set.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(state.search.toLowerCase())));if(state.filter!=='all')rows=rows.filter(x=>String(x.state)===state.filter);return rows}
function controls(){let statuses=[...new Set((store[state.view]||[]).map(x=>x.state))];return `<div class="table-controls"><div class="table-control-left"><span class="listing-icon">${icon("list",18)}</span><span class="records-label">Danh sách <b>${store[state.view].length}</b></span><span class="separator"></span><label class="filter-label">Trạng thái <select id="status-filter" aria-label="Lọc theo trạng thái"><option value="all">Tất cả</option>${statuses.map(x=>`<option value="${escape(x)}" ${state.filter===x?'selected':''}>${escape(x)}</option>`).join('')}</select></label></div><div class="table-control-right"><button class="btn ghost tiny" data-action="export" title="Xuất bản ghi đang lọc">${icon("download",15)} Xuất CSV</button><button class="btn ghost tiny" data-action="reset" title="Đặt lại dữ liệu mô phỏng">↺ Đặt lại</button><button class="btn danger tiny" data-action="bulk-delete" ${state.selected.size?'':'disabled'}>Xóa đã chọn (${state.selected.size})</button><button class="btn icon-label ${state.layout==='table'?'active':''}" data-action="layout-table" aria-label="Dạng bảng">${icon("list",16)} <span>Bảng</span></button><button class="btn icon-label ${state.layout==='cards'?'active':''}" data-action="layout-cards" aria-label="Dạng thẻ">${icon("grid",16)} <span>Thẻ</span></button></div></div>`}
function recordActions(r){return `<span class="row-actions"><button class="row-open" data-record="${escape(r.id)}" title="Xem chi tiết">${icon("eye",16)}</button><button class="row-open" data-edit="${escape(r.id)}" title="Sửa bản ghi">${icon("edit",16)}</button><button class="row-open danger-text" data-delete="${escape(r.id)}" title="Xóa bản ghi">${icon("trash",16)}</button></span>`}
function table(){const cols=columns[state.view],rows=filtered();return `<section class="panel table-panel">${controls()}${rows.length?state.layout==='cards'?`<div class="record-cards">${rows.map(r=>`<div class="record-card"><div><strong>${escape(r.name)}</strong>${badge(r.state)}</div><dl>${cols.slice(1,-1).map(([k,label])=>`<div><dt>${label}</dt><dd>${escape(r[k])}</dd></div>`).join('')}</dl><div class="card-actions"><a class="inline-link" href="${href(state.view,r.id)}" >Chi tiết</a>${recordActions(r)}</div></div>`).join('')}</div>`:`<div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Chọn tất cả bản ghi đang hiển thị" ${rows.every(x=>state.selected.has(x.id))?'checked':''}></th>${cols.map(([,lab])=>`<th>${lab}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${rows.map(r=>`<tr><td><input type="checkbox" data-select="${escape(r.id)}" aria-label="Chọn ${escape(r.id)}" ${state.selected.has(r.id)?'checked':''}></td>${cols.map(([k])=>`<td>${k==='name'?`<a class="inline-link cell-record-link" href="${href(state.view,r.id)}" >${tableCell(r,k,state.view)}</a>`:tableCell(r,k,state.view)}</td>`).join('')}<td>${recordActions(r)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Không tìm thấy bản ghi phù hợp</strong><span>Thử điều chỉnh bộ lọc hoặc từ khóa</span></div>`}<div class="table-footer"><span>Hiển thị ${rows.length} / ${store[state.view].length} bản ghi</span><span>Trang 1 / 1</span></div></section>`}
function modulePage(){let n=(store[state.view]||[]).length;let call=state.view==='shifts'?'Ghi nhận ra / vào ca':state.view==='pda'?'Ghi nhận mượn / trả':state.view==='people'?'Thêm nhân sự':state.view==='minutes'?'Tạo biên bản':state.view==='assets'?'Thêm CCDC':'Thêm công nhật';return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">${icon("plus",16)} ${call}</button>`)}<div class="module-summary">${stat('Tổng bản ghi',String(n).padStart(2,'0'),'Đã ghi nhận','blue','≡')}${stat('Đang xử lý',String((store[state.view]||[]).filter(r=>/Chờ|Đang|Trong ca|Tạm tính/.test(r.state)).length).padStart(2,'0'),'Trạng thái theo dõi','orange','◷')}${stat('Đang hiển thị','01','Tab hiện tại','green','▦')}</div>${table()}</div>`}
function quickLabel(){return state.view==='pda'?'Mượn / trả':state.view==='shifts'?'Quét ca':state.view==='labor'?'Xác nhận công':state.view==='minutes'?'Duyệt biên bản':'Đổi trạng thái'}
function drawer(){if(!state.drawer)return '';const row=store[state.view]?.find(x=>x.id===state.drawer);if(!row)return '';return `<div class="drawer-shade" data-action="close-drawer"></div><aside class="detail-drawer" role="dialog" aria-modal="true" aria-label="Chi tiết ${escape(row.id)}"><div class="detail-head"><div><small>CHI TIẾT HỒ SƠ</small><h2>${escape(row.name)}</h2></div><button class="icon-button" data-action="close-drawer" aria-label="Đóng chi tiết">×</button></div><div class="detail-content"><div class="detail-hero"><span class="detail-icon">${state.view==='people'?'♙':state.view==='pda'?'▯':'▤'}</span><div><strong>${escape(row.name)}</strong><small>${escape(row.id)}</small></div></div>${badge(row.state)}<div class="detail-fields">${(columns[state.view]||[]).slice(1).map(([k,label])=>`<div><span>${label}</span><b>${escape(row[k])}</b></div>`).join('')}</div><div class="detail-tip"></div><div class="drawer-actions"><button class="btn primary" data-edit="${escape(row.id)}">✎ Chỉnh sửa</button><button class="btn ghost" data-quick="${escape(row.id)}">${quickLabel()}</button><button class="btn danger" data-delete="${escape(row.id)}">Xóa</button></div></div></aside>`}
const FIELD_OPTIONS={team:['Pick','Pack','Auto Pack','Điều phối'],shift:['Ca 1','Ca 2'],state:['Đang làm việc','Chờ vào ca','Nghỉ ca','Trong ca','Đã ra ca','Tạm tính','Đã xác nhận','Chưa chấm','Chờ xác nhận','Đã lưu','Sẵn sàng','Đang sử dụng','Cần kiểm tra','Đang mượn','Đã trả'],type:['Bàn giao ca','Thiết bị','Tác nghiệp','An toàn','Kỷ luật'],work:['Pick','Pack','Auto Pack','Điều phối']};
function fieldInput(key,label,value){if(key==='id')return '';const opts=FIELD_OPTIONS[key];const v=String(value??'');if(opts)return `<label>${escape(label)}<select name="${key}" required><option value="">— Chọn —</option>${[...new Set([...opts,v])].filter(Boolean).map(x=>`<option value="${escape(x)}" ${x===v?'selected':''}>${escape(x)}</option>`).join('')}</select></label>`;if(key==='qty')return `<label>${escape(label)}<input type="number" min="0" max="99999" name="${key}" value="${escape(v)}" required></label>`;return `<label>${escape(label)}<input name="${key}" maxlength="120" value="${escape(v)}" placeholder="${escape(label)}" ${key==='name'?'minlength="2" required':''} autocomplete="off"></label>`}
function modal(){if(!state.modal)return '';const key=state.view==='dashboard'?'minutes':state.view;const existing=store[key]?.find(r=>r.id===state.editId);const editing=state.modal==='edit'&&!!existing;const title=editing?`Sửa ${PAGES[key].title.toLowerCase()}`:`Thêm ${PAGES[key].title.toLowerCase()}`;return `<div class="modal-overlay" data-action="close-modal"><section class="modal modal-wide" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span>QUẢN LÝ DỮ LIỆU</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Đóng cửa sổ">${icon("trash",16)}</button></div><form id="record-form"><div class="form-grid">${columns[key].filter(([k])=>k!=='id').map(([k,l])=>fieldInput(k,l,editing?existing[k]:k==='state'?'Chờ xác nhận':'')).join('')}</div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">${editing?'Lưu chỉnh sửa':'Tạo bản ghi'}</button></div></form></section></div>`}
function toast(){return state.notice?`<div class="toast" role="status">${escape(state.notice)}<button data-action="clear-notice" aria-label="Đóng thông báo">×</button></div>`:''}
function render(){document.documentElement.setAttribute('data-theme',state.theme);document.documentElement.style.setProperty('--text-scale',String(state.fontPct/100));if(document.body.dataset.screen==='login'){renderLogin();return}if(!demoSession()){root.innerHTML=`<main class="auth-required"><img src="assets/supra-mark.png" alt="The Supra"><h2>Vui lòng đăng nhập</h2><p>Đăng nhập Quản trị viên trước khi sử dụng giao diện và các tab nghiệp vụ.</p><a class="btn primary" href="index.html">Đăng nhập</a></main>`;return}root.innerHTML=`${side()}<div class="screen-shade ${state.sidebar?'show':''}" data-action="close-nav"></div><div class="app-main">${top()}${state.view==='dashboard'?dashboard():modulePage()}<footer class="site-footer">PickPack 1291 · Hệ thống quản lý vận hành</footer></div>${drawer()}${modal()}${toast()}`}
function renderLogin(){root.innerHTML=`<main class="login-screen"><div class="login-panel"><div class="login-left"><div class="login-brand"><img class="brand-logo" src="assets/supra-mark.png" alt="The Supra"><span>PickPack 1291</span></div><div class="login-art"><div class="art-greeting">QUẢN LÝ VẬN HÀNH</div><h1>Quản lý Pick & Pack tập trung.</h1><p>Nhân sự, công ca, hồ sơ và thiết bị trong cùng một hệ thống.</p><div class="art-metrics"><div><strong>07</strong><span>Phân hệ</span></div><div><strong>03</strong><span>Thiết bị PDA</span></div><div><strong>05</strong><span>Phiên Web</span></div></div></div></div><div class="login-right"><span class="login-kicker">PICKPACK OFFICE</span><h2>Đăng nhập hệ thống</h2><p>Nhập thông tin tài khoản để tiếp tục.</p><form id="login-form" autocomplete="off" class="login-form"><label>Tên đăng nhập<input id="demo-user" name="username" value="" placeholder="Nhập tên đăng nhập" autocomplete="off" required></label><label>Mật khẩu<div class="password-wrap"><input id="demo-password" name="password" type="${state.loginVisible?'text':'password'}" placeholder="Nhập mật khẩu" autocomplete="off" required><button type="button" class="password-toggle" data-action="show-password" aria-label="${state.loginVisible?'Ẩn':'Hiện'} mật khẩu">${state.loginVisible?'Ẩn':'Hiện'}</button></div></label>${state.loginError?`<div class="login-error" role="alert">${escape(state.loginError)}</div>`:''}<button class="btn primary login-submit" type="submit">Đăng nhập <span>→</span></button></form><div class="login-links"><button data-action="theme" class="text-button">${state.theme==='dark'?'☼ Sáng':'☾ Tối'}</button></div></div></div></main>`}
function safeHistory(method,url){try{history[method](null,'',url)}catch{ /* Browser file:// history restrictions do not block UI. */ }}
function closeStuff(){state.sidebar=false;state.modal='';state.drawer='';state.editId=''}
function setView(view){state.view=view;state.search='';state.filter='all';state.drawer='';state.sidebar=false;state.selected.clear();safeHistory('pushState',href(view));render();window.scrollTo(0,0)}
function saveForm(form){const key=state.view==='dashboard'?'minutes':state.view;const fd=new FormData(form);const changes={};for(const [k] of columns[key]){if(k==='id')continue;const value=String(fd.get(k)??'').trim();changes[k]=k==='qty'?Number(value):value||'—'}if(String(changes.name).trim().length<2){state.notice='Tên bản ghi cần từ 2 ký tự';render();return}if(state.modal==='edit'&&state.editId){updateRecord(key,state.editId,changes);state.notice='Cập nhật thành công'}else{const id=`-${key.toUpperCase()}-${Date.now().toString(36).toUpperCase()}`;store[key].unshift({id,...changes});persist();state.notice='Tạo mới thành công'}state.modal='';state.editId='';state.search='';state.filter='all';render()}
function deleteIds(ids){const key=state.view;const matches=store[key].filter(r=>ids.includes(r.id));if(!matches.length)return;if(!window.confirm(`Xóa ${matches.length} bản ghi khỏi ${PAGES[key].title}?`))return;store[key]=store[key].filter(r=>!ids.includes(r.id));persist();state.selected.clear();state.drawer='';safeHistory('replaceState',href());state.notice=`Đã xóa ${matches.length} bản ghi`;render()}
function quickChange(id){const key=state.view;const row=store[key]?.find(x=>x.id===id);if(!row)return;let c={};if(key==='shifts'){const entered=row.state==='Trong ca';c={state:entered?'Đã ra ca':'Trong ca',checkin:entered?row.checkin:'05:35',checkout:entered?'14:05':'—'}}else if(key==='pda'){const borrowed=row.state==='Đang mượn';c={state:borrowed?'Đã trả':'Đang mượn',return:borrowed?'14:05':'—'}}else if(key==='minutes')c={state:'Đã xác nhận'};else if(key==='labor')c={state:'Đã xác nhận'};else if(key==='people')c={state:row.state==='Đang làm việc'?'Nghỉ ca':'Đang làm việc'};else if(key==='assets')c={state:row.state==='Sẵn sàng'?'Đang sử dụng':'Sẵn sàng'};updateRecord(key,id,c);state.notice=`Đã thay đổi trạng thái ${row.id}`;render()}
function exportCSV(){const rows=filtered(),fields=columns[state.view];const quote=s=>'"'+String(s??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.map(([,label])=>quote(label)).join(','),...rows.map(r=>fields.map(([k])=>quote(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`pickpack-${state.view}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);state.notice=`Đã xuất ${rows.length} bản ghi`;render()}
root.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();const fd=new FormData(e.target);const ok=String(fd.get('username')||'').trim()==='admin'&&String(fd.get('password')||'')==='admin';if(!ok){state.loginError='Tên đăng nhập hoặc mật khẩu không đúng';render();return}storageSet(SESSION_KEY,'demo-admin-only');state.loginError='';location.href=href('dashboard');return}if(e.target.id==='record-form'){e.preventDefault();saveForm(e.target)}});
root.addEventListener('click',e=>{
 const nav=e.target.closest('a[data-nav]');if(nav){if(e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();setView(nav.dataset.nav)}return}
 const record=e.target.closest('[data-record]');if(record){state.drawer=record.dataset.record;safeHistory('replaceState',href(state.view,state.drawer));render();return}
 const edit=e.target.closest('[data-edit]');if(edit){state.editId=edit.dataset.edit;state.modal='edit';render();return}
 const del=e.target.closest('[data-delete]');if(del){deleteIds([del.dataset.delete]);return}
 const quick=e.target.closest('[data-quick]');if(quick){quickChange(quick.dataset.quick);return}
 const btn=e.target.closest('[data-action]');if(!btn)return;
 const act=btn.dataset.action;if(act==='close-modal'&&btn.classList.contains('modal-overlay')&&e.target.closest('.modal'))return;
 switch(act){case'toggle-nav':state.sidebar=!state.sidebar;break;case'close-nav':state.sidebar=false;break;
 case'theme':state.theme=state.theme==='light'?'dark':'light';safeHistory('replaceState',document.body.dataset.screen==='app'?href(state.view,state.drawer):'index.html?theme='+state.theme);break;
 case'add':state.editId='';state.modal='new';break;case'close-modal':state.modal='';state.editId='';break;case'close-drawer':state.drawer='';safeHistory('replaceState',href());break;
 case'notifications':state.notice='Thông báo đã được cập nhật';break;
 case'layout-table':state.layout='table';break;case'layout-cards':state.layout='cards';break;case'clear-notice':state.notice='';break;
 case'show-password':{const form=root.querySelector('#login-form');const username=form?.querySelector('#demo-user')?.value||'';const password=form?.querySelector('#demo-password')?.value||'';state.loginVisible=!state.loginVisible;render();root.querySelector('#demo-user').value=username;root.querySelector('#demo-password').value=password;return}
 case'logout':storageRemove(SESSION_KEY);location.href='index.html';return;
 case'bulk-delete':deleteIds([...state.selected]);return;
 case'reset':if(window.confirm('Khôi phục dữ liệu ban đầu? Những chỉnh sửa hiện tại sẽ bị xóa.')){Object.assign(store,seedRecords());persist();state.selected.clear();state.drawer='';state.notice='Đã khôi phục dữ liệu ban đầu';}break;
 case'export':exportCSV();return;
 }
 render();
});
root.addEventListener('input',e=>{if(e.target.id==='global-search'){const input=e.target;state.search=input.value;const pos=input.selectionStart;render();const newInput=root.querySelector('#global-search');if(newInput){newInput.focus();newInput.setSelectionRange(pos,pos)}}});
root.addEventListener('change',e=>{if(e.target.id==='status-filter'){state.filter=e.target.value;state.selected.clear();render();return}if(e.target.id==='select-all'){const ids=filtered().map(x=>x.id);if(e.target.checked)ids.forEach(id=>state.selected.add(id));else ids.forEach(id=>state.selected.delete(id));render();return}if(e.target.matches('[data-select]')){if(e.target.checked)state.selected.add(e.target.dataset.select);else state.selected.delete(e.target.dataset.select);render()}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){const fresh=readRecords();for(const key of Object.keys(store))store[key]=fresh[key];state.notice='Dữ liệu đã được đồng bộ từ tab khác';render()}if(e.key===SESSION_KEY)render()});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.view=PAGES[p.get('view')]?p.get('view'):'dashboard';state.theme=p.get('theme')==='dark'?'dark':'light';state.drawer=p.get('record')||'';state.search='';state.filter='all';state.selected.clear();render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeStuff();render()}});
render();
})();
